@extends('layouts.app') @section('page-title','Patient Support') @section('content')<div class="dashboard-grid align-start"><section class="panel"><h2>Send a support request</h2><form method="post" action="{{ route('patient.support.store') }}">@csrf<label>Category<select name="category">@foreach(['APPOINTMENT','OTP_LOGIN','PAYMENT','LAB_REPORT','INSURANCE','OTHER'] as $v)<option>{{ $v }}</option>@endforeach</select></label><label>Subject<input name="subject" required></label><label>Message<textarea name="message" rows="7" required></textarea></label><button class="btn btn-primary">Send to Office Staff</button></form></section><section><h2>Conversations</h2>@forelse($threads as $t)<article class="panel support-thread"><div class="panel-head"><div><span class="kicker">{{ $t->category }}</span><h3>{{ $t->subject }}</h3></div><x-status :value="$t->status"/></div>@foreach($t->messages as $m)<div class="message {{ $m->sender_user_id===auth()->id()?'mine':'' }}"><p>{{ $m->message }}</p><small>{{ $m->created_at?->format('d M, h:i A') }}</small></div>@endforeach<form method="post" action="{{ route('patient.support.reply',$t) }}">@csrf<div class="inline-input"><input name="message" placeholder="Write a reply" required><button class="btn btn-primary btn-sm">Send</button></div></form></article>@empty<x-empty title="No support conversations"/>@endforelse</section></div>@endsection